INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Projektkontrolle nur während der Durchführung eines Projekts relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Planung und Abschluss betroffen"}, {"text": "Ja", "correct": false, "because": "Kontinuierlicher Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Projektkontrolle?', 3, '[{"text": "Projektziele sicherstellen", "correct": true, "because": "Überwacht Fortschritt und Abweichungen"}, {"text": "Maximale Dokumentation", "correct": false, "because": "Nicht primär"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Systematisch besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Projektkontrolle?', 5, '[{"text": "Fortschrittsüberwachung", "correct": true, "because": "Misst Zielerreichung"}, {"text": "Risikomanagement", "correct": true, "because": "Erkennt Gefahren"}, {"text": "Farbcodierung", "correct": false, "because": "Nur gestalterisch"}, {"text": "Musikwiedergabe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Projektkontrolle erkennt Abweichungen. b) Sie ersetzt die Planung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ergänzt, ersetzt nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Projektkontrolle?', 4, '[{"text": "Meilensteine", "correct": false, "because": "Markieren Fortschritt"}, {"text": "Kostenüberwachung", "correct": false, "because": "Sichert Budget"}, {"text": "Büroausstattung", "correct": true, "because": "Irrelevant für Kontrolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Projektkontrolle nur für große Projekte nötig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen Kontrolle"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt die Projektkontrolle?', 3, '[{"text": "Projektmanagement-Software", "correct": true, "because": "Wie Jira oder MS Project"}, {"text": "Texteditor", "correct": false, "because": "Ungeeignet für Kontrolle"}, {"text": "Manuelle Notizen", "correct": false, "because": "Software effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kennzahlen sind für die Projektkontrolle wichtig?', 5, '[{"text": "Kostenabweichung", "correct": true, "because": "Zeigt Budgeteinhaltung"}, {"text": "Zeitfortschritt", "correct": true, "because": "Misst Zeitplan"}, {"text": "Mitarbeiteranzahl", "correct": false, "because": "Sekundär"}, {"text": "Bürofläche", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Projektkontrolle nutzt Berichte. b) Sie vermeidet alle Risiken. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) minimiert, nicht vermeidet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Projektkontrolle?', 4, '[{"text": "Fortschrittsberichte", "correct": false, "because": "Zeigen Status"}, {"text": "Risikoanalyse", "correct": false, "because": "Erkennt Gefahren"}, {"text": "Musikwiedergabe", "correct": true, "because": "Irrelevant für Kontrolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Projektkontrolle dasselbe wie Projektplanung?', 2, '[{"text": "Nein", "correct": true, "because": "Planung definiert, Kontrolle überwacht"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Phasen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen die Projektkontrolle?', 4, '[{"text": "Meilensteinanalyse", "correct": true, "because": "Überprüft Fortschritt"}, {"text": "Earned Value Management", "correct": true, "because": "Misst Leistung"}, {"text": "Grafikdesign", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Projektkontrolle immer teuer ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten abhängig von Tools"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig teuer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Projektkontrolle?', 3, '[{"text": "Abweichungsanalyse", "correct": true, "because": "Erkennt Probleme früh"}, {"text": "Maximale Berichte", "correct": false, "because": "Klarheit wichtiger"}, {"text": "Manuelle Checks", "correct": false, "because": "Systeme effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Projektkontrolle überwacht Zeitpläne. b) Sie ersetzt das Team.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) unterstützt, nicht ersetzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Projektkontrolle?', 5, '[{"text": "Frühzeitige Problemerkennung", "correct": true, "because": "Vermeidet Verzögerungen"}, {"text": "Zieltreue", "correct": true, "because": "Sichert Ergebnisse"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher Nachteil"}, {"text": "Einmalige Nutzung", "correct": false, "because": "Kontinuierlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Projektkontrolle unwichtig?', 3, '[{"text": "Kostenmanagement", "correct": false, "because": "Sichert Budget"}, {"text": "Fortschrittskontrolle", "correct": false, "because": "Überwacht Zeitplan"}, {"text": "Bildschirmauflösung", "correct": true, "because": "Kein Kontrollfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Projektkontrolle auch Risiken berücksichtigt?', 2, '[{"text": "Ja", "correct": true, "because": "Teil des Risikomanagements"}, {"text": "Nein", "correct": false, "because": "Risiken zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt Projektkontrolle die Kommunikation im Team?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzt Kommunikation"}, {"text": "Ja", "correct": false, "because": "Kommunikation bleibt nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur Projektkontrolle?', 4, '[{"text": "Überwachung eines Softwareprojekts", "correct": true, "because": "Kontrolliert Zeit und Budget"}, {"text": "Musikwiedergabe", "correct": false, "because": "Keine Projektarbeit"}, {"text": "Bildbearbeitung", "correct": false, "because": "Kreative Aufgabe"}]');
